window.RP_SESSION={"id":"S-cafa869d1773","messages":[{"id":"Plane-0000901","time":"2026-09-20T21:41:00+09:00","room":"Plane","name":"아르메리아","profile":"테이레시아스","identity":"reviewed","type":"dialogue","body":"아르메리아는 거울 앞에 앉았습니다.","characters":["P-d80a97449dfc"]},{"id":"Plane-0000902","time":"2026-09-20T21:43:00+09:00","room":"Plane","name":"아르메리아","profile":"테이레시아스","identity":"reviewed","type":"dialogue","body":"그리고는 앞머리를 매만지기 시작합니다. 원래 그녀의 앞머리는 눈 사이에 조금 긴 길이로 늘어뜨린 삼지창머리죠.","characters":["P-d80a97449dfc"]},{"id":"Plane-0000903","time":"2026-09-20T21:44:00+09:00","room":"Plane","name":"아르메리아","profile":"테이레시아스","identity":"reviewed","type":"dialogue","body":"다만 머리를 이리저리 손대다 보니까 왠지 5:5 비율의 가르마 앞머리가 더 나아보이기도 했습니다.","characters":["P-d80a97449dfc"]},{"id":"Plane-0000904","time":"2026-09-20T21:44:00+09:00","room":"Plane","name":"아르메리아","profile":"테이레시아스","identity":"reviewed","type":"dialogue","body":"햐여 아르메리아는 이마에 손을 가져다대고 머리카락을 2갈래로 나눠 양 옆에 두었다가 다시 조심스럽게 모아서 눈 사이에 두었다가를 반복했습니다.","characters":["P-d80a97449dfc"]},{"id":"Plane-0000905","time":"2026-09-20T21:45:00+09:00","room":"Plane","name":"아르메리아","profile":"테이레시아스","identity":"reviewed","type":"dialogue","body":"()","characters":["P-d80a97449dfc"]},{"id":"Plane-0000906","time":"2026-09-20T21:45:00+09:00","room":"Plane","name":"아르메리아","profile":"테이레시아스","identity":"reviewed","type":"dialogue","body":"그러다가 30분이 지났습니다. 이러다 평생 결정을 못하면 어쩌죠?","characters":["P-d80a97449dfc"]},{"id":"Plane-0000907","time":"2026-09-20T23:33:00+09:00","room":"Plane","name":"아르메리아","profile":"테이레시아스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-d80a97449dfc"]}]};
